export function downloadAllowance(maxDownloads: number, locale: Locale) {
  const c = digitalProductCopy[locale];
  return maxDownloads === 0 ? c.unlimited : `${new Intl.NumberFormat(locale).format(maxDownloads)} ${c.downloads}`;
}
